function taxOwed(bands: number[][], income: number): number {
  let prev = 0, tax = 0;
  for (const [upper, percent] of bands) {
    if (income <= prev) break;
    tax += ((Math.min(upper, income) - prev) * percent) / 100;
    prev = upper;
  }
  return tax;
}

